import {ENCLOSURE_STYLES,CLOSURE_FIELDS,CLOSURE_KEYS,CLOSURE_NOTES,normalizeClosure,closureDefaults} from './enclosure.js';
import {parseLength} from './dimensions.js';

export function enclosureInspector(e,esc){const c=normalizeClosure(e.closure,e);return `<section class="inspector-section closure-card"><h3>Enclosure style</h3><label>Lid / closure<select data-closure-style>${Object.entries(ENCLOSURE_STYLES).map(([k,v])=>`<option value="${k}"${c.type===k?' selected':''}>${v}</option>`).join('')}</select></label><p class="hint">${esc(CLOSURE_NOTES[c.type])}</p>${c.type!=='plain'?'<button class="wide" data-closure-settings>Adjust closure dimensions</button>':''}<p class="fine">Box dimensions exclude projecting tabs and hinge hardware. Closure details use interior space.</p></section>`;}
export function initEnclosureUI(api){const $=s=>document.querySelector(s),commit=c=>api.commit(()=>api.project().enclosure.closure=c);
 document.addEventListener('change',e=>{if(!e.target.matches('[data-closure-style]'))return;try{const enc=api.project().enclosure,prior=normalizeClosure(enc.closure,enc);commit(normalizeClosure({...(prior.type==='plain'?closureDefaults(enc):prior),type:e.target.value},enc));api.notify('Enclosure style updated. Use Open or Transparent to inspect the closure.');}catch(err){api.notify(err.message);api.refresh();}});
 document.addEventListener('click',e=>{if(e.target.closest('[data-closure-settings]'))open();});
 function open(){const p=api.project(),enc=p.enclosure,c=normalizeClosure(enc.closure,enc),factor=p.units==='in'?25.4:1;api.openModal('Adjust '+ENCLOSURE_STYLES[c.type].toLowerCase(),`<form id="closureForm"><p>${api.esc(CLOSURE_NOTES[c.type])}</p><div class="fields two">${CLOSURE_KEYS[c.type].map(k=>`<label>${CLOSURE_FIELDS[k]} (${p.units})<input name="${k}" type="text" value="${+(c[k]/factor).toFixed(4)}"></label>`).join('')}</div><p class="fine">Accepts mm, inches and fractions. Geometry is nominal; check your materials, fasteners and manufacturing allowances. Existing surface features remain editable at their original face coordinates.</p><p id="closureError" class="form-error" role="alert" hidden></p><div class="modal-actions"><button class="primary" type="submit">Apply closure</button><button type="button" data-close>Cancel</button></div></form>`);
  $('#closureForm').onsubmit=e=>{e.preventDefault();try{const next={...c};for(const input of e.currentTarget.querySelectorAll('[name]'))next[input.name]=parseLength(input.value,p.units);commit(normalizeClosure(next,api.project().enclosure));$('#modal').close();api.notify('Closure dimensions updated.');}catch(err){$('#closureError').hidden=false;$('#closureError').textContent=err.message;}};
 }
 return {open};
}
